/**
 * Runtime configuration, read once at startup from the environment.
 */

export interface Config {
  /** Width of a rollup window, in milliseconds. */
  windowMs: number;
  /** Hard cap on samples held per series before the oldest are dropped. */
  maxSamples: number;
  /** How long a sample stays queryable, in milliseconds. */
  retentionMs: number;
}

export class ConfigError extends Error {
  readonly key: string;

  constructor(key: string, message: string) {
    super(`${key}: ${message}`);
    this.name = "ConfigError";
    this.key = key;
  }
}

export const DEFAULT_CONFIG: Config = {
  windowMs: 60_000,
  maxSamples: 10_000,
  retentionMs: 24 * 60 * 60 * 1000,
};

function readPositiveInt(
  env: Record<string, string | undefined>,
  key: string,
  fallback: number,
): number {
  const raw = env[key];
  if (raw === undefined || raw === "") return fallback;
  const parsed = Number(raw);
  if (!Number.isInteger(parsed) || parsed <= 0) {
    throw new ConfigError(key, `expected a positive integer, got "${raw}"`);
  }
  return parsed;
}

/**
 * Build a Config from the environment, falling back to DEFAULT_CONFIG per key.
 * Throws ConfigError on a present-but-unusable value rather than silently
 * falling back — a typo in a deploy env should be loud.
 */
export function loadConfig(
  env: Record<string, string | undefined> = process.env,
): Config {
  return {
    windowMs: readPositiveInt(env, "ROLLUP_WINDOW_MS", DEFAULT_CONFIG.windowMs),
    maxSamples: readPositiveInt(env, "ROLLUP_MAX_SAMPLES", DEFAULT_CONFIG.maxSamples),
    retentionMs: readPositiveInt(env, "ROLLUP_RETENTION_MS", DEFAULT_CONFIG.retentionMs),
  };
}
===SUMMARY===
/**
 * Collapse a window series into a single human- and wire-readable summary.
 */

import type { Window } from "./rollup.ts";

export interface Summary {
  series: string;
  /** Number of samples across every window. */
  count: number;
  mean: number;
  min: number;
  max: number;
  /** Bounds of the covered span, or null when there is nothing to cover. */
  from: number | null;
  to: number | null;
}

export function summarize(windows: Window[], series: string): Summary {
  if (windows.length === 0) {
    return { series, count: 0, mean: 0, min: 0, max: 0, from: null, to: null };
  }

  let count = 0;
  let sum = 0;
  let min = Infinity;
  let max = -Infinity;

  for (const window of windows) {
    count += window.count;
    sum += window.sum;
    min = Math.min(min, window.min);
    max = Math.max(max, window.max);
  }

  return {
    series,
    count,
    mean: count === 0 ? 0 : sum / count,
    min,
    max,
    from: windows[0].from,
    to: windows[windows.length - 1].to,
  };
}

export function formatSummary(summary: Summary): string {
  if (summary.count === 0) {
    return `${summary.series}: no samples`;
  }
  const mean = summary.mean.toFixed(2);
  return `${summary.series}: n=${summary.count} mean=${mean} min=${summary.min} max=${summary.max}`;
}
===VALIDATE===
/**
 * The one place a sample is admitted or rejected. Everything downstream may
 * assume a Sample is well-formed.
 */

export interface Sample {
  /** Series name — non-empty, no whitespace. */
  series: string;
  /** The measured value; finite. */
  value: number;
  /** Epoch milliseconds. */
  at: number;
}

export class ValidationError extends Error {
  readonly field: string;

  constructor(field: string, message: string) {
    super(`${field}: ${message}`);
    this.name = "ValidationError";
    this.field = field;
  }
}

export function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

const SERIES_PATTERN = /^[a-z][a-z0-9_.-]*$/;

export function isValidSeries(name: unknown): name is string {
  return typeof name === "string" && SERIES_PATTERN.test(name);
}

/**
 * Coerce an unknown payload into a Sample, or throw. Never returns a partially
 * valid object — callers get all-or-nothing.
 */
export function validateSample(input: unknown): Sample {
  if (input === null || typeof input !== "object") {
    throw new ValidationError("sample", "expected an object");
  }
  const candidate = input as Record<string, unknown>;

  if (!isValidSeries(candidate.series)) {
    throw new ValidationError(
      "series",
      "expected a lowercase name matching [a-z][a-z0-9_.-]*",
    );
  }
  if (!isFiniteNumber(candidate.value)) {
    throw new ValidationError("value", "expected a finite number");
  }
  if (!isFiniteNumber(candidate.at) || !Number.isInteger(candidate.at)) {
    throw new ValidationError("at", "expected epoch milliseconds as an integer");
  }
  if (candidate.at < 0) {
    throw new ValidationError("at", "expected a non-negative timestamp");
  }

  return { series: candidate.series, value: candidate.value, at: candidate.at };
}
===CLOCK===
/**
 * Time is injected, never read from the global — every window boundary and
 * retention sweep is testable because of it.
 */

export interface Clock {
  now(): number;
}

export class SystemClock implements Clock {
  now(): number {
    return Date.now();
  }
}

/** A clock that only moves when you move it. Used by the tests. */
export class FixedClock implements Clock {
  private current: number;

  constructor(current: number) {
    this.current = current;
  }

  now(): number {
    return this.current;
  }

  advance(ms: number): void {
    if (ms < 0) throw new RangeError("cannot advance a clock backwards");
    this.current += ms;
  }

  set(at: number): void {
    this.current = at;
  }
}
===INDEX===
/**
 * Wiring. Everything above is injectable; this is the one place that decides
 * which real implementations get used.
 */

import type { Clock } from "./clock.ts";
import { SystemClock } from "./clock.ts";
import type { Config } from "./config.ts";
import { loadConfig } from "./config.ts";
import { IngestQueue } from "./ingest.ts";
import { MemoryStore } from "./store.ts";
import type { Router } from "./router.ts";
import { createRouter } from "./router.ts";

export interface Service {
  config: Config;
  store: MemoryStore;
  queue: IngestQueue;
  router: Router;
  /** Move queued samples into the store and expire anything past retention. */
  tick(): void;
}

export function createService(
  config: Config = loadConfig(),
  clock: Clock = new SystemClock(),
): Service {
  const store = new MemoryStore(config.maxSamples);
  const queue = new IngestQueue(config.maxSamples);
  const router = createRouter(store, queue, config, clock);

  return {
    config,
    store,
    queue,
    router,
    tick(): void {
      for (const sample of queue.drain()) store.put(sample);
      store.prune(clock.now() - config.retentionMs);
    },
  };
}

export function main(): void {
  const service = createService();
  // Drain whatever the queue holds and expire anything past retention before
  // reporting: the numbers below are about the store, and the store is only
  // current once the queue has been moved into it.
  service.tick();
  const series = service.store.series();
  process.stdout.write(
    `rollup service ready — window ${service.config.windowMs}ms, ` +
      `${series.length} series, ${service.queue.droppedCount()} dropped\n`,
  );
}

if (process.argv[1] && process.argv[1].endsWith("index.ts")) {
  main();
}

