export class MemoryStore {
  private readonly buckets = new Map<string, Sample[]>();
  private readonly maxPerSeries: number;
  private readonly maxSeries: number;
  private refusedSeries = 0;

  constructor(maxPerSeries: number, maxSeries: number) {
    if (!Number.isInteger(maxPerSeries) || maxPerSeries <= 0) {
      throw new RangeError("maxPerSeries must be a positive integer");
    }
    if (!Number.isInteger(maxSeries) || maxSeries <= 0) {
      throw new RangeError("maxSeries must be a positive integer");
    }
    this.maxPerSeries = maxPerSeries;
    this.maxSeries = maxSeries;
  }

  /**
   * Insert a sample, keeping the series bucket ordered by timestamp.
   *
   * A sample for a series not already tracked is refused once the store
   * already holds `maxSeries` distinct series — the cap bounds how many
   * series can exist, not how deep any one of them runs.
   */
  put(sample: Sample): void {
    let bucket = this.buckets.get(sample.series);
    if (bucket === undefined) {
      if (this.buckets.size >= this.maxSeries) {
        this.refusedSeries += 1;
        return;
      }
      bucket = [];
      this.buckets.set(sample.series, bucket);
    }
    const at = insertionPoint(bucket, sample.at);
    bucket.splice(at, 0, sample);
    if (bucket.length > this.maxPerSeries) {
      bucket.splice(0, bucket.length - this.maxPerSeries);
    }
  }

  /** How many samples `put` has refused for naming a series beyond the cap. */
  refusedSeriesCount(): number {
    return this.refusedSeries;
  }

